using System;
using System.Diagnostics;

// PROGRAM: Mengamati Latensi Alur Memori dan Bus Komputer
// Membandingkan akses sekuensial (Cache Hit) vs akses acak (Cache Miss / Bus Traffic)
const int Size = 5_000_000;
int[] array = new int[Size];
for (int i = 0; i < Size; i++) array[i] = i;

// 1. Akses Sekuensial (Jalur data bus teratur, hardware prefetcher aktif)
var sw = Stopwatch.StartNew();
long sum = 0;
for (int i = 0; i < Size; i++)
{
    sum += array[i];
}
sw.Stop();
Console.WriteLine($"[1] Akses Sekuensial: {sw.ElapsedMilliseconds} ms (Sum: {sum})");

// TODO: Buat eksperimen dengan stride/lompatan indeks (misal: i += 64)
// dan amati bagaimana latensi berubah akibat beban transfer bus data!
Console.WriteLine("Selesai menguji jalur memori.");

