using System;

public class MemoryArchitecture
{
    public static long CalculateMaxMemoryGb(int addressBits)
    {
        if (addressBits < 30) return 0;
        if (addressBits >= 63) return long.MaxValue / (1024L * 1024L * 1024L);
        return 1L << (addressBits - 30);
    }

    public static void Main()
    {
        Console.WriteLine($"32-bit: {CalculateMaxMemoryGb(32)} GB");
        Console.WriteLine($"36-bit: {CalculateMaxMemoryGb(36)} GB");
    }
}
